/**
 * The 3D preview's side of Rust, for the demo: the allowed folders, the
 * file stat, the `hangar-model` URL scheme, and saving a capture.
 *
 * There is one model on this pretend disk, the sample under demo/models
 * (generated by scripts/demo-model.mjs, no third-party asset), placed in the
 * hangar-ai workspace where an agent would have written it. The scheme is a
 * `fetch` stand-in: a URL that modelUrl() built for that path is answered
 * with the bundled file, anything else with the 404 Rust would give.
 */
import sampleUrl from "../models/sample.glb?url";

/** Where the sample sits in the demo workspace (backend/state, "hangar-ai"). */
export const SAMPLE_MODEL_PATH = "C:\\dev\\hangar-ai\\demo\\models\\sample.glb";

/** Its modification time: the demo never rewrites it, so the preview never reloads it. */
const MODIFIED_MS = Date.now();

let roots: string[] = [];
let sampleSize = 0;

/** The browser's own fetch, which the scheme below stands in front of. */
const nativeFetch: typeof fetch = window.fetch.bind(window);

const normalize = (path: string) => path.replace(/\//g, "\\").replace(/\\+$/, "").toLowerCase();

export function allowRoots(list: string[]) {
  roots = list.map(normalize);
}

async function sizeOfSample(): Promise<number> {
  if (!sampleSize) sampleSize = (await (await nativeFetch(sampleUrl)).arrayBuffer()).byteLength;
  return sampleSize;
}

/** The same refusals as src-tauri/src/model.rs, worded for an agent. */
export async function stat(path: string) {
  const wanted = normalize(path);
  if (!roots.some((root) => wanted === root || wanted.startsWith(`${root}\\`))) {
    throw new Error(`${path} is outside the folders Hangar may read (the workspace and its worktrees).`);
  }
  if (wanted !== normalize(SAMPLE_MODEL_PATH)) {
    throw new Error(
      `${path} does not exist. This is the browser demo: its only model is ${SAMPLE_MODEL_PATH}.`,
    );
  }
  return { path: SAMPLE_MODEL_PATH, size: await sizeOfSample(), modifiedMs: MODIFIED_MS };
}

/** A capture "saved": the browser's own download, under the name the dialog proposed. */
export function savePng(path: string, data: string) {
  const link = document.createElement("a");
  link.href = `data:image/png;base64,${data}`;
  link.download = path.split(/[\\/]/).pop() || "capture.png";
  link.click();
}

/** The path a hangar-model URL stands for, or null for any other URL. */
function schemePath(url: string): string | null {
  const match = /^(?:https?:\/\/hangar-model\.localhost|hangar-model:\/\/localhost)\/(.*)$/i.exec(url);
  if (!match) return null;
  return match[1]
    .split("/")
    .map((part) => decodeURIComponent(part))
    .join("\\");
}

/**
 * Installed once, by the backend: the app fetches models (and a glTF's
 * textures) from the scheme, which only the desktop app serves.
 */
export function installModelScheme() {
  window.fetch = (input: RequestInfo | URL, init?: RequestInit) => {
    const url = typeof input === "string" ? input : input instanceof URL ? input.href : input.url;
    const path = schemePath(url);
    if (path === null) return nativeFetch(input, init);
    const allowed = roots.some((root) => normalize(path).startsWith(`${root}\\`));
    if (!allowed) return Promise.resolve(new Response("outside every allowed folder", { status: 403 }));
    if (normalize(path) !== normalize(SAMPLE_MODEL_PATH)) {
      return Promise.resolve(new Response("no such file", { status: 404 }));
    }
    return nativeFetch(sampleUrl, init);
  };
}
